-- 000128: email providers -- OAuth (Gmail / Yahoo / Outlook) + local
-- sendmail, provider logos, and the SMTP credentials-shape fix.
--
-- The runtime registry reads these from the embedded seed
-- (crates/unified-core/provider_registry_seed.json); this migration
-- keeps the durable table from 000127 in sync: a logo column, logo
-- values for the 9 existing email rows, the rewritten SMTP shape,
-- and the 4 new email rows. The INSERTs below are generated by
-- docs/integration/c12_generate_registry_seed_sql.py (which now emits
-- the logo column); the UPDATEs are hand-written.

ALTER TABLE provider_registry_definitions
    ADD COLUMN IF NOT EXISTS logo TEXT;

-- Logos for the 9 existing email providers.
UPDATE provider_registry_definitions SET logo = 'email-mailchimp' WHERE family = 'email' AND provider_id = 'mailchimp';
UPDATE provider_registry_definitions SET logo = 'email-brevo' WHERE family = 'email' AND provider_id = 'brevo';
UPDATE provider_registry_definitions SET logo = 'email-sendgrid' WHERE family = 'email' AND provider_id = 'sendgrid';
UPDATE provider_registry_definitions SET logo = 'email-mailgun' WHERE family = 'email' AND provider_id = 'mailgun';
UPDATE provider_registry_definitions SET logo = 'email-postmark' WHERE family = 'email' AND provider_id = 'postmark';
UPDATE provider_registry_definitions SET logo = 'email-ses' WHERE family = 'email' AND provider_id = 'ses';
UPDATE provider_registry_definitions SET logo = 'email-resend' WHERE family = 'email' AND provider_id = 'resend';
UPDATE provider_registry_definitions SET logo = 'email-sparkpost' WHERE family = 'email' AND provider_id = 'sparkpost';
UPDATE provider_registry_definitions SET logo = 'email-smtp' WHERE family = 'email' AND provider_id = 'smtp';

-- Rewritten SMTP shape: host, port, TLS mode, auth, from (
-- addition A). The old shape only had sender_email / webhook_secret /
-- test_mode; the adapter now delivers directly to the configured server.
UPDATE provider_registry_definitions
    SET display_name = 'SMTP (Custom server)',
        credentials_shape = '[{"name":"host","label":"SMTP host","type":"text","required":true,"secret":false,"placeholder":"smtp.example.com","description":"SMTP server hostname."},{"name":"port","label":"SMTP port","type":"number","required":true,"secret":false,"placeholder":"587","description":"SMTP port: 587 for STARTTLS, 465 for implicit TLS."},{"name":"tls_mode","label":"TLS mode","type":"select","required":true,"secret":false,"placeholder":"starttls","description":"starttls (port 587), implicit (port 465), or none (plaintext, local servers only)."},{"name":"username","label":"SMTP username","type":"text","required":false,"secret":false,"placeholder":"user@example.com","description":"SMTP username (usually the sender address). Leave empty for servers without authentication."},{"name":"password","label":"SMTP password","type":"password","required":false,"secret":true,"description":"SMTP password. Stored encrypted; never shown again."},{"name":"sender_email","label":"Default sender email","type":"email","required":true,"secret":false,"placeholder":"news@example.com","description":"From address used when a send does not supply its own."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]'::jsonb,
        notes = 'Direct SMTP delivery to any server: host, port, TLS mode and credentials live on this connection. Port 465 uses implicit TLS, other TLS ports use STARTTLS. SMTP has no webhooks; bounce and complaint handling is not available for this provider.'
    WHERE family = 'email' AND provider_id = 'smtp';

-- The 4 new email providers (generated INSERTs).
INSERT INTO provider_registry_definitions (family, provider_id, display_name, logo, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'gmail', 'Gmail', 'email-gmail', 'https://smtp.gmail.com', NULL, NULL, NULL, NULL, '["smtp.gmail.com","accounts.google.com","oauth2.googleapis.com"]', '{"transactional":true,"bulk":false,"templates":false,"webhooks":false,"tracking":false,"sandbox":false}', '[]', '[{"name":"client_id","label":"OAuth client ID","type":"text","required":true,"secret":false,"placeholder":"123456789012-abc.apps.googleusercontent.com","description":"OAuth client ID from Google Cloud Console (APIs & Services > Credentials)."},{"name":"client_secret","label":"OAuth client secret","type":"password","required":true,"secret":true,"description":"OAuth client secret from the provider console. Stored encrypted; never shown again."},{"name":"sender_email","label":"Sender email","type":"email","required":true,"secret":false,"placeholder":"you@gmail.com","description":"Gmail address that sends the mail (the linked Google account). Used as the XOAUTH2 identity."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'gmail', FALSE, FALSE, 'Sends through smtp.gmail.com:587 with OAuth2 (XOAUTH2) - no app passwords. Link the Google account from the connection (OAuth authorize); the access token refreshes automatically. Scope: https://mail.google.com/.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, logo, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'yahoo', 'Yahoo Mail', 'email-yahoo', 'https://smtp.mail.yahoo.com', NULL, NULL, NULL, NULL, '["smtp.mail.yahoo.com","api.login.yahoo.com"]', '{"transactional":true,"bulk":false,"templates":false,"webhooks":false,"tracking":false,"sandbox":false}', '[]', '[{"name":"client_id","label":"OAuth client ID","type":"text","required":true,"secret":false,"placeholder":"dj0yJmk9QUJDREVGR0gmazEyMw--","description":"OAuth client ID (Consumer Key) from the Yahoo Developer Network app."},{"name":"client_secret","label":"OAuth client secret","type":"password","required":true,"secret":true,"description":"OAuth client secret from the provider console. Stored encrypted; never shown again."},{"name":"sender_email","label":"Sender email","type":"email","required":true,"secret":false,"placeholder":"you@yahoo.com","description":"Yahoo Mail address that sends the mail (the linked Yahoo account). Used as the XOAUTH2 identity."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'yahoo', FALSE, FALSE, 'Sends through smtp.mail.yahoo.com:587 with OAuth2 (XOAUTH2). Link the Yahoo account from the connection (OAuth authorize); the access token refreshes automatically. Scope: mail-w.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, logo, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'outlook', 'Outlook / Microsoft 365', 'email-outlook', 'https://smtp.office365.com', NULL, NULL, NULL, NULL, '["smtp.office365.com","login.microsoftonline.com"]', '{"transactional":true,"bulk":false,"templates":false,"webhooks":false,"tracking":false,"sandbox":false}', '[]', '[{"name":"client_id","label":"OAuth client ID","type":"text","required":true,"secret":false,"placeholder":"00000000-0000-0000-0000-000000000000","description":"Application (client) ID from Microsoft Entra (Azure AD) app registration."},{"name":"client_secret","label":"OAuth client secret","type":"password","required":true,"secret":true,"description":"OAuth client secret from the provider console. Stored encrypted; never shown again."},{"name":"sender_email","label":"Sender email","type":"email","required":true,"secret":false,"placeholder":"you@outlook.com","description":"Outlook address that sends the mail (the linked Microsoft account). Used as the XOAUTH2 identity."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'outlook', FALSE, FALSE, 'Sends through smtp.office365.com:587 with OAuth2 (XOAUTH2). Link the Microsoft account from the connection (OAuth authorize); the access token refreshes automatically. Scope: https://outlook.office365.com/SMTP.Send offline_access.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;
INSERT INTO provider_registry_definitions (family, provider_id, display_name, logo, base_url, sandbox_base_url, api_style, auth_scheme, webhook_signature_header, allowed_hosts, capabilities, currencies, credentials_shape, models, default_model, adapter_kind, needs_endpoint, needs_delegate, notes, builtin) VALUES ('email', 'sendmail', 'Local Sendmail', 'email-sendmail', NULL, NULL, NULL, NULL, NULL, '[]', '{"transactional":true,"bulk":true,"templates":false,"webhooks":false,"tracking":false,"sandbox":false}', '[]', '[{"name":"sender_email","label":"Default sender email","type":"email","required":false,"secret":false,"placeholder":"noreply@example.com","description":"From address used when a send does not supply its own; defaults to unified@localhost."},{"name":"sender_name","label":"Default sender name","type":"text","required":false,"secret":false,"placeholder":"Example News","description":"Display name shown next to the sender email."},{"name":"test_mode","label":"Test mode (sandbox)","type":"boolean","required":false,"secret":false,"description":"When on, mail is accepted by the provider sandbox where one exists, otherwise recorded as a simulated delivery and never sent."}]', '[]', NULL, 'sendmail', FALSE, FALSE, 'Delivers through the local sendmail binary (/usr/sbin/sendmail or /usr/bin/sendmail), like the PHP mail() default. No credentials needed. The binary must exist on the server; the connection test reports whether it is present.', TRUE) ON CONFLICT (family, provider_id) DO NOTHING;

